INSERT INTO memory_state (project_id, key, value, updated_at) VALUES ('nitesh:markets', 'strategy:ath-momentum', '"{\n  \"name\": \"ATH Momentum Swing Strategy\",\n  \"started\": \"2026-06-07\",\n  \"status\": \"testing\",\n  \"universe\": \"NSE Nifty 500 \u2014 ATH within 60 days + above 220 DMA\",\n  \"entry_layers\": [\n    \"Layer 1: Stock at ATH within 60 days (Chartink)\",\n    \"Layer 2: Stock above 220 DMA (Chartink)\",\n    \"Layer 3: Sector index above 220 DMA (manual check before buying)\"\n  ],\n  \"position_size\": 25000,\n  \"max_positions\": \"7-8\",\n  \"max_per_sector\": 3,\n  \"entry\": \"Next day open after all 3 layers confirmed on daily close\",\n  \"stop_loss_hard\": \"10% from entry\",\n  \"stop_loss_dma\": \"Daily close below 220 DMA\",\n  \"trailing_stop\": \"7% from highest price, activates once position up 20%+\",\n  \"profit_target\": \"None \u2014 hold until stop or trailing stop\",\n  \"review\": \"Biweekly \u2014 fresh Chartink scan, Claude ranks, Nitesh buys top 1-3\",\n  \"backtest_insight\": \"Feb 2026: 5 banks exited simultaneously due to sector correction. Layer 3 (sector index filter) would have prevented all 5 bad entries.\",\n  \"saved_to\": \"life/markets/strategies.md\"\n}"'::jsonb, '2026-06-06T19:58:03.760159') ON CONFLICT DO NOTHING;
